CREATE TABLE IF NOT EXISTS `drawing_symbol_recognition_versions` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`document_id` text NOT NULL,`document_version_id` text NOT NULL,`drawing_intake_version_id` text NOT NULL,`version_number` integer NOT NULL,`input_fingerprint` text NOT NULL,`output_fingerprint` text NOT NULL,`engine_version` text NOT NULL,`status` text NOT NULL,`summary` text NOT NULL,`superseded_at` text,`created_by` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`),FOREIGN KEY (`document_id`) REFERENCES `documents`(`id`),FOREIGN KEY (`document_version_id`) REFERENCES `document_versions`(`id`),FOREIGN KEY (`drawing_intake_version_id`) REFERENCES `drawing_intake_versions`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `drawing_symbol_document_version_idx` ON `drawing_symbol_recognition_versions` (`document_id`,`version_number`);
CREATE INDEX IF NOT EXISTS `drawing_symbol_current_idx` ON `drawing_symbol_recognition_versions` (`document_id`,`superseded_at`);
CREATE TABLE IF NOT EXISTS `drawing_symbol_definitions` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`recognition_version_id` text NOT NULL,`definition_key` text NOT NULL,`abbreviation` text,`explicit_label` text,`description` text,`original_abbreviation` text,`original_explicit_label` text,`original_description` text,`source_page` integer NOT NULL,`bounding_box` text,`shape_signatures` text NOT NULL,`confidence` integer NOT NULL,`evidence_text` text NOT NULL,`extraction_method` text NOT NULL,`review_status` text DEFAULT 'Needs Review' NOT NULL,`reviewed_by` text,`reviewed_at` text,`review_reason` text,`merged_into_definition_id` text,`derived_from_definition_id` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`),FOREIGN KEY (`recognition_version_id`) REFERENCES `drawing_symbol_recognition_versions`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `drawing_symbol_definition_key_idx` ON `drawing_symbol_definitions` (`recognition_version_id`,`definition_key`);
CREATE INDEX IF NOT EXISTS `drawing_symbol_definition_project_idx` ON `drawing_symbol_definitions` (`project_id`,`review_status`,`explicit_label`);
CREATE TABLE IF NOT EXISTS `drawing_symbol_source_geometries` (`id` text PRIMARY KEY NOT NULL,`definition_id` text NOT NULL,`shape_signature` text NOT NULL,`source_page` integer NOT NULL,`bounding_box` text NOT NULL,`geometry` text NOT NULL,`geometry_fingerprint` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`definition_id`) REFERENCES `drawing_symbol_definitions`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `drawing_symbol_geometry_fingerprint_idx` ON `drawing_symbol_source_geometries` (`definition_id`,`geometry_fingerprint`);
CREATE TABLE IF NOT EXISTS `drawing_symbol_occurrences` (`id` text PRIMARY KEY NOT NULL,`recognition_version_id` text NOT NULL,`definition_id` text,`original_definition_id` text,`occurrence_key` text NOT NULL,`page_number` integer NOT NULL,`bounding_box` text NOT NULL,`shape_signature` text NOT NULL,`nearby_text` text,`match_basis` text NOT NULL,`confidence` integer NOT NULL,`review_status` text DEFAULT 'Needs Review' NOT NULL,`source_geometry` text,`reviewed_by` text,`reviewed_at` text,`review_reason` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`recognition_version_id`) REFERENCES `drawing_symbol_recognition_versions`(`id`),FOREIGN KEY (`definition_id`) REFERENCES `drawing_symbol_definitions`(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `drawing_symbol_occurrence_key_idx` ON `drawing_symbol_occurrences` (`recognition_version_id`,`occurrence_key`);
CREATE INDEX IF NOT EXISTS `drawing_symbol_occurrence_definition_idx` ON `drawing_symbol_occurrences` (`recognition_version_id`,`definition_id`,`page_number`);
CREATE INDEX IF NOT EXISTS `drawing_symbol_unknown_idx` ON `drawing_symbol_occurrences` (`recognition_version_id`,`page_number`) WHERE `definition_id` IS NULL;
CREATE TABLE IF NOT EXISTS `drawing_symbol_review_events` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`recognition_version_id` text NOT NULL,`entity_type` text NOT NULL,`entity_id` text NOT NULL,`action` text NOT NULL,`previous_value` text,`new_value` text NOT NULL,`reason` text NOT NULL,`actor_user_id` text NOT NULL,`request_id` text NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`),FOREIGN KEY (`recognition_version_id`) REFERENCES `drawing_symbol_recognition_versions`(`id`));
CREATE INDEX IF NOT EXISTS `drawing_symbol_review_entity_idx` ON `drawing_symbol_review_events` (`entity_type`,`entity_id`,`created_at`);
